  if ( s == SPEC_NONE || s == _spec )
  {
    if ( unsigned spell_id = dbc->class_ability_id( type, _spec, name ) )
    {
      const spell_data_t* spell = dbc->spell( spell_id );
      if ( spell->id() == spell_id && as<int>( spell->level() ) <= true_level )
